-- Safety checkpoint of all current business/auth tables before task identifiers and reminders.
-- Snapshot tables are infrastructure-only: no application route exports or reads them.
CREATE TABLE system_backup_v85_schema AS SELECT type,name,tbl_name,sql FROM sqlite_master WHERE sql IS NOT NULL AND name NOT LIKE 'sqlite_%' AND name NOT LIKE 'system_backup_%';
CREATE TABLE system_backup_v85_manifest(table_name TEXT PRIMARY KEY,row_count INTEGER NOT NULL,snapshot_count INTEGER NOT NULL,verified INTEGER NOT NULL CHECK(verified=1),recorded_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE system_backup_v85_activities AS SELECT * FROM activities;
INSERT INTO system_backup_v85_manifest(table_name,row_count,snapshot_count,verified) SELECT 'activities',(SELECT count(*) FROM activities),(SELECT count(*) FROM system_backup_v85_activities),CASE WHEN NOT EXISTS(SELECT * FROM activities EXCEPT SELECT * FROM system_backup_v85_activities) AND NOT EXISTS(SELECT * FROM system_backup_v85_activities EXCEPT SELECT * FROM activities) THEN 1 ELSE 0 END;
