INSERT INTO system_backup_v85_manifest(table_name,row_count,snapshot_count,verified) SELECT 'activity_edits',(SELECT count(*) FROM activity_edits),(SELECT count(*) FROM system_backup_v85_activity_edits),CASE WHEN NOT EXISTS(SELECT * FROM activity_edits EXCEPT SELECT * FROM system_backup_v85_activity_edits) AND NOT EXISTS(SELECT * FROM system_backup_v85_activity_edits EXCEPT SELECT * FROM activity_edits) THEN 1 ELSE 0 END;
